      "settingsAutomationDescription": "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F\u043C\u0438, \u0432\u043D\u0435\u0448\u043D\u0438\u043C\u0438 \u0440\u0435\u0441\u0443\u0440\u0441\u0430\u043C\u0438, \u043F\u043E\u0438\u0441\u043A\u043E\u043C \u0438 \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E\u0439 \u0441\u0438\u043D\u0445\u0440\u043E\u043D\u0438\u0437\u0430\u0446\u0438\u0435\u0439 \u043C\u0435\u0436\u0434\u0443 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430\u043C\u0438.",
      "settingsSecurityDescription": "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043F\u043E\u043B\u0438\u0442\u0438\u043A\u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F, \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0439, \u0446\u0435\u043B\u043E\u0441\u0442\u043D\u043E\u0441\u0442\u0438, \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A \u0445\u043E\u0441\u0442\u0430\u043C \u0438 \u044D\u043A\u0441\u043F\u0435\u0440\u0438\u043C\u0435\u043D\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0441\u0440\u0435\u0434\u0441\u0442\u0432 \u0437\u0430\u0449\u0438\u0442\u044B.",
      "settingsRecoveryDescription": "\u0417\u0430\u0449\u0438\u0442\u0430 \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449\u0430, \u0431\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u044B\u0439 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A ScriptVault \u0438\u043B\u0438 \u043F\u043E\u043B\u043D\u044B\u0439 \u0441\u0431\u0440\u043E\u0441 \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u044F.",
      "settingsAutosaveMost": "\u0411\u043E\u043B\u044C\u0448\u0438\u043D\u0441\u0442\u0432\u043E \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u043E\u0432 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438",
      "settingsSecurityRuntime": "\u0412\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0435",
      "settingsSecurityPermissions": "\u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u044F",
      "settingsSecurityTrust": "\u0414\u043E\u0432\u0435\u0440\u0438\u0435",
      "settingsSecurityHostAccess": "\u0414\u043E\u0441\u0442\u0443\u043F \u043A \u0445\u043E\u0441\u0442\u0430\u043C",
      "settingsSecurityRuntimeGroupTitle": "\u0421\u0440\u0435\u0434\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F \u0438 \u043F\u0435\u0441\u043E\u0447\u043D\u0438\u0446\u0430",
      "settingsSecurityRuntimeGroupDescription": "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u043F\u043E\u0441\u043E\u0431 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u0441\u043A\u0438\u0445 \u0441\u043A\u0440\u0438\u043F\u0442\u043E\u0432 \u0438 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u044B\u0435 \u043A\u043E\u043D\u0442\u0435\u043A\u0441\u0442\u044B \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0430.",
      "settingsSecurityPermissionsGroupTitle": "\u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0441\u0442\u0440\u0430\u043D\u0438\u0446 \u0438 \u0441\u0435\u0442\u0438",
